import{_ as t,o,c as a,a3 as i}from"./chunks/framework.BU8W3uSP.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{"order":30},"headers":[],"relativePath":"introduction/concepts.md","filePath":"introduction/concepts.md"}'),r={name:"introduction/concepts.md"};function s(n,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="system-time-vs-application-time" tabindex="-1">System time vs. application time <a class="header-anchor" href="#system-time-vs-application-time" aria-label="Permalink to &quot;System time vs. application time&quot;">​</a></h2><p>Two different questions hide behind the word &quot;temporal&quot;:</p><ul><li><strong>System time</strong>: <em>when did the database hold this row?</em> It is recorded automatically. Every insert, update and delete opens a new version and closes the previous one. <strong>This is what Hindsight tracks.</strong></li><li><strong>Application time</strong>, also called valid time: <em>when was this fact true in the real world?</em> For example, &quot;this tariff applies from March 1&quot;. The application chooses the dates. PostgreSQL 19 supports it natively with <code>FOR PORTION OF</code> and <code>WITHOUT OVERLAPS</code>. Hindsight does not implement it; the API is shaped so it can be added later without breaking changes.</li></ul><h2 id="versions-and-periods" tabindex="-1">Versions and periods <a class="header-anchor" href="#versions-and-periods" aria-label="Permalink to &quot;Versions and periods&quot;">​</a></h2><p>Each row in a history table is a <strong>version</strong>: a snapshot of the entity&#39;s versioned columns, plus the <strong>period</strong> during which it was the current row.</p><ul><li>Periods are <strong>half-open</strong>: <code>[valid_from, valid_to)</code> includes <code>valid_from</code> and excludes <code>valid_to</code>. When one version closes at 09:05, the next opens at exactly 09:05, with no gap and no overlap.</li><li>Both columns are <code>timestamptz</code>, in UTC.</li><li>The current version has <code>valid_to = &#39;infinity&#39;</code>, not <code>NULL</code>: it compares and indexes correctly.</li></ul><p>So &quot;the version at instant <code>t</code>&quot; is always one predicate, <code>valid_from &lt;= t AND valid_to &gt; t</code>, and it matches at most one row per entity.</p><p>Here is a policy created at 09:00, activated at 09:05 and deleted at 10:00:</p><table tabindex="0"><thead><tr><th><code>operation</code></th><th><code>status</code></th><th><code>valid_from</code></th><th><code>valid_to</code></th><th></th></tr></thead><tbody><tr><td>1 (insert)</td><td><code>Draft</code></td><td>09:00</td><td>09:05</td><td></td></tr><tr><td>2 (update)</td><td><code>Active</code></td><td>09:05</td><td>10:00</td><td></td></tr><tr><td>3 (delete)</td><td><code>Active</code></td><td>10:00</td><td>10:00</td><td>tombstone</td></tr></tbody></table><h2 id="tombstones" tabindex="-1">Tombstones <a class="header-anchor" href="#tombstones" aria-label="Permalink to &quot;Tombstones&quot;">​</a></h2><p>A delete closes the open version and writes a <strong>tombstone</strong>: a row with the last values and an empty period (<code>valid_from = valid_to</code>). It never matches a point-in-time query, so after 10:00 <code>AsOf</code> finds nothing, but it records <em>when</em> the policy was deleted and <em>who</em> did it. <a href="/hindsight-efcore/1.4/querying/history"><code>History&lt;T&gt;</code></a> returns tombstones; <a href="/hindsight-efcore/1.4/querying/as-of"><code>AsOf</code></a>, <a href="/hindsight-efcore/1.4/querying/all-versions"><code>AllVersions</code></a> and the <a href="/hindsight-efcore/1.4/querying/time-ranges">time-range operators</a> do not.</p><h2 id="one-timestamp-per-transaction" tabindex="-1">One timestamp per transaction <a class="header-anchor" href="#one-timestamp-per-transaction" aria-label="Permalink to &quot;One timestamp per transaction&quot;">​</a></h2><p>All history rows written by one <code>SaveChanges</code> share one instant, so a change that spans several entities is consistent at every point in time. The trigger writer uses PostgreSQL&#39;s <code>now()</code>, the transaction timestamp; the interceptor writer takes one value from <code>TimeProvider</code> per <code>SaveChanges</code>.</p><h2 id="two-tables-not-a-flag" tabindex="-1">Two tables, not a flag <a class="header-anchor" href="#two-tables-not-a-flag" aria-label="Permalink to &quot;Two tables, not a flag&quot;">​</a></h2><p>The main table stays as it is. History is a separate table:</p><ul><li><strong>without foreign keys</strong> back to the main table, because a deleted row&#39;s history must survive it;</li><li><strong>without the original&#39;s <code>NOT NULL</code>, unique or check constraints</strong>, because a unique index on a history table breaks on the second edit.</li></ul><p>It contains every mapped property of the entity except the ones you <a href="/hindsight-efcore/1.4/configuration/temporal-entities#excluding-properties">exclude</a>.</p><h2 id="change-context" tabindex="-1">Change context <a class="header-anchor" href="#change-context" aria-label="Permalink to &quot;Change context&quot;">​</a></h2><p>The database knows that a row changed. Only the application knows who was acting, on behalf of which request, and why. Hindsight stores that as a <code>ChangeContext</code> (who changed it, their display name, correlation id, reason and JSON extras) on every version. See <a href="/hindsight-efcore/1.4/writing/change-context">Change context</a>.</p><h2 id="history-writers" tabindex="-1">History writers <a class="header-anchor" href="#history-writers" aria-label="Permalink to &quot;History writers&quot;">​</a></h2><p>Something has to turn each change into history rows. Hindsight can do it from a trigger in the database or from an interceptor in the application. Both produce the same history table, so switching is one migration. See <a href="/hindsight-efcore/1.4/writing/history-writers">Choosing a history writer</a>.</p><h2 id="historical-results-are-read-only" tabindex="-1">Historical results are read-only <a class="header-anchor" href="#historical-results-are-read-only" aria-label="Permalink to &quot;Historical results are read-only&quot;">​</a></h2><p>Everything a historical query returns is a detached snapshot. Saving one back would rewrite the present with the past, so Hindsight throws instead. See <a href="/hindsight-efcore/1.4/querying/restrictions">Rules for historical queries</a>.</p>',24)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
